apply = '--apply' in sys.argv
total = 0
for rel, subs in sorted(FIX.items()):
    src = COPIES[0] + rel
    if not os.path.exists(src):
        sys.stdout.write(u'НЕТ ФАЙЛА: %s\n' % rel)
        continue
    txt = io.open(src, encoding='utf-8').read()
    hits = 0
    for old, new in subs:
        n = txt.count(old)
        if n == 0:
            sys.stdout.write(u'  не найдено в %s: %s\n' % (rel, old[:60]))
        hits += n
        txt = txt.replace(old, new)
    total += hits
    sys.stdout.write(u'%-48s %d\n' % (rel, hits))
    if apply:
        for base in COPIES:
            p = base + rel
            d = os.path.dirname(p)
            if not os.path.isdir(d):
                os.makedirs(d)
            with io.open(p, 'w', encoding='utf-8', newline='') as f:
                f.write(txt)
sys.stdout.write(u'ИТОГО: %d\n' % total)
